package ru.voicerooms;import android.content.Context;import android.content.SharedPreferences;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import android.util.Base64;import java.security.KeyStore;import javax.crypto.Cipher;import javax.crypto.KeyGenerator;import javax.crypto.SecretKey;import javax.crypto.spec.GCMParameterSpec;public final class SessionStore {  private final SharedPreferences prefs;  public SessionStore(Context context) {    prefs = context.getSharedPreferences("voice_session", Context.MODE_PRIVATE);  }  private SecretKey key() throws Exception {    KeyStore ks = KeyStore.getInstance("AndroidKeyStore");    ks.load(null);    SecretKey found = (SecretKey) ks.getKey("voice-session-v2", null);    if (found != null) return found;    KeyGenerator generator =        KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore");    generator.init(        new KeyGenParameterSpec.Builder(                "voice-session-v2", KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)            .build());    return generator.generateKey();  }  public synchronized void save(String token) throws Exception {    Cipher c = Cipher.getInstance("AES/GCM/NoPadding");    c.init(Cipher.ENCRYPT_MODE, key());    prefs        .edit()        .putString("iv", Base64.encodeToString(c.getIV(), Base64.NO_WRAP))        .putString(            "value",            Base64.encodeToString(                c.doFinal(token.getBytes(java.nio.charset.StandardCharsets.UTF_8)), Base64.NO_WRAP))        .apply();  }  public synchronized String read() {    try {      String iv = prefs.getString("iv", null), data = prefs.getString("value", null);      if (iv == null || data == null) return "";      Cipher c = Cipher.getInstance("AES/GCM/NoPadding");      c.init(          Cipher.DECRYPT_MODE, key(), new GCMParameterSpec(128, Base64.decode(iv, Base64.NO_WRAP)));      return new String(          c.doFinal(Base64.decode(data, Base64.NO_WRAP)), java.nio.charset.StandardCharsets.UTF_8);    } catch (Exception ignored) {      return "";    }  }  public synchronized void clear() {    prefs.edit().clear().apply();  }}